alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(user_id uuid, other_id uuid)
returns boolean as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = $1 and addressee_id = $2 and status = 'accepted')
       or (requester_id = $2 and addressee_id = $1 and status = 'accepted')
  );
$$ language sql security definer;

create policy "Allow authenticated users to read public posts"
on public.posts
for select
to authenticated
using (audience = 'public');

create policy "Allow authenticated users to read friends' posts"
on public.posts
for select
to authenticated
using (
  audience = 'friends'
  and public.is_friend(auth.uid(), author_id)
);

create policy "Allow authenticated users to read own posts"
on public.posts
for select
to authenticated
using (author_id = auth.uid());

create policy "Allow anonymous users to read public posts"
on public.posts
for select
to anon
using (audience = 'public');

create policy "Allow authenticated users to insert own posts"
on public.posts
for insert
to authenticated
with check (author_id = auth.uid());

create policy "Allow authenticated users to update own posts"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (author_id = auth.uid());

create policy "Allow authenticated users to delete own posts"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "Allow authenticated users to insert friend requests"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
  and addressee_id <> auth.uid()
  and status = 'pending'
);

create policy "Allow addressee to accept friend request"
on public.friendships
for update
to authenticated
using (
  addressee_id = auth.uid()
  and status = 'pending'
)
with check (
  addressee_id = auth.uid()
  and status = 'accepted'
);

create policy "Allow either party to delete friendship"
on public.friendships
for delete
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

create policy "Allow either party to read friendships"
on public.friendships
for select
to authenticated
using (
  requester_id = auth.uid()
  or addressee_id = auth.uid()
);

grant select on public.posts to anon, authenticated;
grant insert, update, delete on public.posts to authenticated;
grant select, insert, update, delete on public.friendships to authenticated;
