```sql
alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create function public.is_friend(user_id uuid, target_id uuid)
returns boolean as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = $1 and addressee_id = $2)
       or (requester_id = $2 and addressee_id = $1)
    and status = 'accepted'
  );
$$ language sql security definer;

create policy "R1: Authenticated users can read posts based on audience"
on public.posts
for select
to authenticated
using (
  audience = 'public'
  or audience = 'friends' and public.is_friend(auth.uid(), author_id)
  or author_id = auth.uid()
);

create policy "R1: Anonymous users can only read public posts"
on public.posts
for select
to anon
using (audience = 'public');

create policy "R2: Users can insert their own posts"
on public.posts
for insert
to authenticated
with check (
  author_id = auth.uid()
  and audience in ('public', 'friends', 'only_me')
);

create policy "R2: Users can update their own posts"
on public.posts
for update
to authenticated
using (author_id = auth.uid())
with check (
  author_id = auth.uid()
  and audience in ('public', 'friends', 'only_me')
);

create policy "R2: Users can delete their own posts"
on public.posts
for delete
to authenticated
using (author_id = auth.uid());

create policy "R3: Authenticated users can send friend requests"
on public.friendships
for insert
to authenticated
with check (
  requester_id = auth.uid()
