alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create function public.is_auction_active(auction_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.auctions a
    where a.id = auction_id
      and a.ends_at > now()
  );
$$ language sql security definer;

create function public.get_highest_bid(auction_id bigint)
returns numeric as $$
  select coalesce(a.highest_bid, 0)
  from public.auctions a
  where a.id = auction_id;
$$ language sql security definer;

create function public.get_min_increment(auction_id bigint)
returns numeric as $$
  select a.min_increment
  from public.auctions a
  where a.id = auction_id;
$$ language sql security definer;

create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric as $$
  declare
    v_auction_exists boolean;
    v_auction_ended boolean;
    v_current_highest_bid numeric;
    v_min_increment numeric;
    v_new_highest_bid numeric;
    v_seller_id uuid;
    v_bidder_id uuid;
  begin
    -- Check if user is authenticated
    if auth.role() = 'anon' then
      raise exception 'User must be signed in to place a bid';
    end if;

    -- Check if auction exists
    select exists (select 1 from public.auctions where id = p_auction_id) into v_auction_exists;
    if not v_auction_exists then
      raise exception 'Auction does not exist';
    end if;

    -- Check if auction has ended
    select (ends_at <= now()) into v_auction_ended from public.auctions where id = p_auction_id;
    if v_auction_ended then
      raise exception 'Auction has ended';
    end if;

    -- Get seller ID
    select seller_id into v_seller_id from public.auctions where id = p_auction_id;

    -- Check if caller is the seller
    if auth.uid() = v_seller_id then
      raise exception 'Sellers cannot place bids on their own auctions';
    end if;

    -- Get current highest bid and min increment
    select highest_bid, min_increment into v_current_highest_bid, v_min_increment
    from public.auctions
    where id = p_auction_id;

    -- Check if amount is too low
    if v_current_highest_bid is null then
      -- No bids yet, must be at least starting price
      if p_amount < (select starting_price from public.auctions where id = p_auction_id) then
        raise exception 'Bid amount must be at least the starting price';
      end if;
    else
      -- Must be at least highest bid + min increment
      if p_amount < (v_current_highest_bid + v_min_increment) then
        raise exception 'Bid amount must be at least the highest bid plus the minimum increment';
      end if;
    end if;

    -- Insert the bid
    insert into public.bids (auction_id, bidder_id, amount, placed_at)
    values (p_auction_id, auth.uid(), p_amount, now());

    -- Update the auction's highest bid
    update public.auctions
    set highest_bid = p_amount,
        highest_bidder = auth.uid()
    where id = p_auction_id;

    return p_amount;
  end;
$$ language plpgsql security definer;

-- R1: Signed-in users can see every auction
create policy "authenticated_users_can_view_auctions"
on public.auctions
for select
to authenticated
using (true);

-- R1: Bidders can see their own bids
create policy "authenticated_users_can_view_own_bids"
on public.bids
for select
to authenticated
using (bidder_id = auth.uid());

