create function public.is_instructor_of_class(p_class_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.classes c
    where c.id = p_class_id and c.instructor_id = auth.uid()
  );
$$ language sql security definer;

create function public.is_enrolled_in_class(p_class_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.class_spots cs
    where cs.class_id = p_class_id and cs.user_id = auth.uid()
  );
$$ language sql security definer;

create function public.is_waitlisted_in_class(p_class_id bigint)
returns boolean as $$
  select exists (
    select 1 from public.class_spots cs
    where cs.class_id = p_class_id and cs.user_id = auth.uid() and cs.status = 'waitlisted'
  );
$$ language sql security definer;

create function public.get_enrolled_count(p_class_id bigint)
returns integer as $$
  select count(*) from public.class_spots cs
  where cs.class_id = p_class_id and cs.status = 'enrolled';
$$ language sql security definer;

create policy "R1: Signed-in users can see every class"
on public.classes
for select
to authenticated
using (true);

create policy "R1: Members can see their own spots"
on public.class_spots
for select
to authenticated
using (user_id = auth.uid());

create policy "R1: Instructors can see every spot in the classes they teach"
on public.class_spots
for select
to authenticated
using (public.is_instructor_of_class(class_id));

create policy "R2: Members can join a class as themselves"
on public.class_spots
for insert
to authenticated
with check (
  user_id = auth.uid()
  and (
    (status = 'enrolled' and public.get_enrolled_count(class_id) < (select capacity from public.classes c where c.id = class_id))
    or (status = 'waitlisted' and public.get_enrolled_count(class_id) >= (select capacity from public.classes c where c.id = class_id))
  )
);

create policy "R3: Members can move their own waitlisted spot to enrolled only when there is room"
on public.class_spots
for update
to authenticated
using (
  user_id = auth.uid()
  and status = 'waitlisted'
  and public.get_enrolled_count(class_id) < (select capacity from public.classes c where c.id = class_id)
)
with check (
  user_id = auth.uid()
  and status = 'enrolled'
);

create policy "R3: Members can leave a class by deleting their own spot"
on public.class_spots
for delete
to authenticated
using (user_id = auth.uid());

create policy "R4: Instructors can remove any spot from the classes they teach"
on public.class_spots
for delete
to authenticated
using (public.is_instructor_of_class(class_id));

create policy "R5: Nobody can change classes through the app"
on public.classes
for all
to authenticated
using (false)
with check (false);

create policy "R5: Anonymous visitors cannot see or change anything"
on public.classes
for all
to anon
using (false)
with check (false);

create policy "R5: Anonymous visitors cannot see or change anything"
on public.class_spots
for all
to anon
using (false)
with check (false);

